package api.mem_purchase_p;
import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.core.Authentication; import org.springframework.web.server.ResponseStatusException; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class MemPurchaseControllerTest { @Mock MemPurchaseService service; @Mock Authentication auth; @InjectMocks MemPurchaseController controller;
 @Test @DisplayName("UT-BE-MEMPURCHASE-CTRL-001 로그인 입주민이 구매 주문을 생성한다") void order(){ when(auth.getName()).thenReturn("user"); MemPurchaseDTO d=new MemPurchaseDTO(); when(service.createOrder("user",d)).thenReturn(d); assertThat(controller.createOrder(auth,d)).isSameAs(d); }
 @Test @DisplayName("UT-BE-MEMPURCHASE-CTRL-002 로그인 입주민이 결제를 승인한다") void confirm(){ when(auth.getName()).thenReturn("user"); MemPurchaseDTO.Payment p=mock(MemPurchaseDTO.Payment.class); when(service.confirmPayment("user",p)).thenReturn(p); assertThat(controller.confirmPayment(auth,p)).isSameAs(p); }
 @Test @DisplayName("UT-BE-MEMPURCHASE-CTRL-003 인증 없는 구매 주문을 거부한다") void orderUnauthorized(){ assertThatThrownBy(()->controller.createOrder(null,new MemPurchaseDTO())).isInstanceOf(ResponseStatusException.class); verifyNoInteractions(service); }
 @Test @DisplayName("UT-BE-MEMPURCHASE-CTRL-004 인증 없는 결제 승인을 거부한다") void confirmUnauthorized(){ assertThatThrownBy(()->controller.confirmPayment(null,mock(MemPurchaseDTO.Payment.class))).isInstanceOf(ResponseStatusException.class); verifyNoInteractions(service); } }
